# Static check. Not an experiment version.
# Compare the T6 overlay with the overlay the T3m runners used.
# Recompute one numeric section column from the image table at 0x60029b28.
# Do not edit this file after it has run.
import csv
import hashlib
import json
import struct
from pathlib import Path

ROOT = Path('.')
IMAGE = ROOT / 'inputs/00_0100_50000020.decoded.bin'
T6 = ROOT / 'ref/analysis/button-af/readiness/t6-afon-target-size-position/out/overlay-changed-bytes.csv'
T3M = ROOT / 'ref/analysis/button-af/readiness/t3m-afon-editor-state-leak/out/overlay-changed-bytes.csv'
POSE = ROOT / 'ref/tasks/T7-orientation-producer/run-20261119-072701/work/scripts/pose.mjs'
OUT_JSON = ROOT / 'work/out/overlay-diff-t8.json'
OUT_CSV = ROOT / 'work/out/overlay-combined-t8.csv'
OUT_TITLES = ROOT / 'work/out/static-titles-t8.json'

BASE_PAGE_OFFSET = 0x020
FLASH_VIEW = 0x50000000
SECTION_ROW = 12
EXPECT_TABLE = 0x60029B28
SECTION_LOAD = [0xf1, 0xe3, 0x8f, 0xff, 0xe3, 0xcd, None, None, 0x00, 0x00, 0x82, 0x8c, 0x14, 0xf9, 0x14, 0x0c, 0xf1, 0xe2, 0xfc, 0xd2]
SECTION_SWITCH = [0x04, 0xa0, 0x01, 0xc0, None, 0xa0, None, 0xc1, None, 0x28, 0xff, 0x54, 0xfc, 0xdc, None, None, None, None, 0xf3, 0x80, 0xf0, 0xf4]
PERMITTED_SECTION7 = {0x610bf5e3, 0x610bf5e4, 0x610bf5e5}


def u32(buf, off):
    return struct.unpack_from('<I', buf, off)[0]


def cached(addr):
    if 0xA0000000 <= addr < 0xC0000000:
        return (addr - 0x40000000) & 0xFFFFFFFF
    return addr & 0xFFFFFFFF


def bytes_at(buf, off, pat):
    if off < 0 or off + len(pat) > len(buf):
        return False
    return all(p is None or buf[off + i] == p for i, p in enumerate(pat))


def one_at(buf, pat):
    hits = []
    start = 0
    first = pat[0]
    while True:
        o = buf.find(bytes([first]), start)
        if o < 0 or o + len(pat) > len(buf):
            break
        if bytes_at(buf, o, pat):
            hits.append(o)
        start = o + 1
    if len(hits) != 1:
        raise SystemExit(f'section load pattern hits {len(hits)}, want 1')
    return hits[0]


def call_at(buf, o):
    op = buf[o]
    if op == 0xdd:
        disp = struct.unpack_from('<i', buf, o + 1)[0]
        return o + disp
    if op == 0xcd:
        disp = struct.unpack_from('<h', buf, o + 1)[0]
        return o + disp
    if op == 0xfc and buf[o + 1] == 0xff:
        disp = struct.unpack_from('<i', buf, o + 2)[0]
        return o + disp
    if op == 0xfa and buf[o + 1] == 0xff:
        disp = struct.unpack_from('<h', buf, o + 2)[0]
        return o + disp
    raise SystemExit(f'not a call at file offset {o:#x}')


def image_base(buf):
    hits = []
    limit = min(0x400, len(buf) - 8)
    for o in range(limit + 1):
        if buf[o] == 0xfc and buf[o + 1] == 0xdc and buf[o + 6] == 0xf0 and buf[o + 7] == 0xf4:
            hits.append(o)
    if len(hits) != 1:
        raise SystemExit(f'image base jumps {len(hits)}, want 1')
    target = u32(buf, hits[0] + 2)
    if (target & 0xfff) < BASE_PAGE_OFFSET:
        raise SystemExit(f'image base target {target:#x} is below the page offset')
    return (target & ~0xfff) | BASE_PAGE_OFFSET


def section_ends(buf, base, switch_off):
    if not bytes_at(buf, switch_off, SECTION_SWITCH):
        raise SystemExit(f'section end switch at {switch_off:#x} does not match')
    count = buf[switch_off + 6]
    jt = u32(buf, switch_off + 14) - base
    ends = []
    for n in range(1, count + 1):
        case_off = u32(buf, jt + 4 * (n - 1)) - base
        if not (0 <= case_off and case_off + 6 <= len(buf)):
            raise SystemExit(f'section {n} case is outside the image')
        if buf[case_off] != 0xfc or buf[case_off + 1] != 0xcc:
            raise SystemExit(f'section {n} case is not mov imm32,d0')
        ends.append(u32(buf, case_off + 2))
    return ends


def load_sections(buf, base):
    at = one_at(buf, SECTION_LOAD)
    table = u32(buf, at + 20)
    switch_off = call_at(buf, at + 5)
    ends = section_ends(buf, base, switch_off)
    rows = []
    table_off = table - base
    for i, end in enumerate(ends):
        row = table_off + SECTION_ROW * i
        start = u32(buf, row)
        src = u32(buf, row + 4)
        flag = u32(buf, row + 8)
        file_off = src - FLASH_VIEW - BASE_PAGE_OFFSET
        if start != (base + file_off) & 0xFFFFFFFF:
            raise SystemExit(f'section {i + 1} does not copy in place: start {start:#x}')
        if not (start <= end <= base + len(buf)):
            raise SystemExit(f'section {i + 1} end {end:#x} is outside')
        rows.append({'n': i + 1, 'start': start, 'end': end, 'flag': flag})
    return table, rows


def section_of(sections, addr):
    c = cached(addr)
    for row in sections:
        if row['start'] <= c < row['end']:
            return row['n']
    return None


def load_csv(path):
    with path.open(newline='', encoding='utf-8') as f:
        reader = csv.DictReader(f)
        rows = list(reader)
        fields = list(reader.fieldnames)
    by_addr = {}
    for rec in rows:
        addr = int(rec['runtime_address'], 16)
        by_addr[addr] = rec
    return fields, rows, by_addr


def sha256(path):
    h = hashlib.sha256()
    data = path.read_bytes()
    h.update(data)
    return h.hexdigest(), len(data)


def grab_titles(path, session, prefix):
    out = []
    if not path.exists():
        return out
    with path.open(encoding='utf-8') as f:
        for line in f:
            if '"id":"' + prefix not in line and '"id": "' + prefix not in line:
                continue
            try:
                row = json.loads(line)
            except json.JSONDecodeError:
                continue
            if session and row.get('session') not in (None, session):
                continue
            ident = row.get('id')
            if not isinstance(ident, str) or not ident.startswith(prefix):
                continue
            texts = row.get('texts') or row.get('titleText') or []
            out.append({
                'id': ident,
                'title': row.get('title'),
                'highlight': row.get('highlight'),
                'screen': row.get('screen'),
                'texts': texts[:8] if isinstance(texts, list) else texts,
            })
    return out


def main():
    OUT_JSON.parent.mkdir(parents=True, exist_ok=True)
    image = IMAGE.read_bytes()
    base = image_base(image)
    table, sections = load_sections(image, base)
    t6_fields, t6_rows, t6 = load_csv(T6)
    t3_fields, t3_rows, t3 = load_csv(T3M)
    only_t6 = sorted(set(t6) - set(t3))
    only_t3 = sorted(set(t3) - set(t6))
    diffs = []
    for addr in sorted(set(t6) & set(t3)):
        a = t6[addr]
        b = t3[addr]
        proposed_diff = int(a['proposed_byte'], 16) != int(b['proposed_byte'], 16)
        stock_diff = int(a['stock_byte'], 16) != int(b['stock_byte'], 16)
        if proposed_diff or stock_diff:
            diffs.append({
                'addr': f'{addr:#x}',
                't6_proposed': a['proposed_byte'],
                't3m_proposed': b['proposed_byte'],
                't6_stock': a['stock_byte'],
                't3m_stock': b['stock_byte'],
                't6_source': a.get('source'),
                't3m_source': b.get('source'),
                'stock_diff': stock_diff,
                'proposed_diff': proposed_diff,
            })
    profile = [d for d in diffs if d['t6_source'] == 'profile-read' and d['proposed_diff'] and not d['stock_diff']]
    other = [d for d in diffs if d not in profile]
    problems = []
    if only_t6 or only_t3:
        problems.append('address sets differ')
    if other:
        problems.append('differences other than the profile-read proposed bytes')
    if len(profile) != 15:
        problems.append(f'profile-read proposed differences {len(profile)}, want 15')
    if table != EXPECT_TABLE:
        problems.append(f'table {table:#x} is not {EXPECT_TABLE:#x}')

    counts = {}
    bad_section = []
    out_rows = []
    fieldnames = ['component_offset', 'runtime_address', 'stock_byte', 'proposed_byte', 'source', 'purpose', 'section']
    for rec in t6_rows:
        addr = int(rec['runtime_address'], 16)
        off = int(rec['component_offset'], 16)
        stock = int(rec['stock_byte'], 16)
        if off >= len(image) or image[off] != stock:
            problems.append(f'stock mismatch at {addr:#x}')
        n = section_of(sections, addr)
        if n is None:
            problems.append(f'{addr:#x} is in no loaded section')
        else:
            counts[n] = counts.get(n, 0) + 1
            if addr in PERMITTED_SECTION7:
                if n != 7:
                    problems.append(f'permitted call site {addr:#x} is section {n}')
            elif n in (6, 7):
                bad_section.append(f'{addr:#x} section {n}')
        out_rows.append({
            'component_offset': rec['component_offset'],
            'runtime_address': rec['runtime_address'],
            'stock_byte': rec['stock_byte'],
            'proposed_byte': rec['proposed_byte'],
            'source': rec.get('source', ''),
            'purpose': rec.get('purpose', ''),
            'section': '' if n is None else str(n),
        })
    if bad_section:
        problems.extend(bad_section)
    missing = sorted(PERMITTED_SECTION7 - set(t6))
    if missing:
        problems.append('missing permitted rows ' + ' '.join(f'{a:#x}' for a in missing))
    header_count = 0
    if out_rows:
        header_count = 1

    pose_sha, pose_len = sha256(POSE)
    report = {
        'ok': not problems,
        't6_rows': len(t6_rows),
        't3m_rows': len(t3_rows),
        't6_fields': t6_fields,
        't3m_fields': t3_fields,
        'only_t6': [f'{a:#x}' for a in only_t6],
        'only_t3m': [f'{a:#x}' for a in only_t3],
        'diff_count': len(diffs),
        'profile_read_diffs': profile,
        'other_diffs': other,
        'section_counts': {str(k): counts[k] for k in sorted(counts)},
        'section_column': 'one numeric column named section',
        'section_headers_written': header_count,
        'table': f'{table:#x}',
        'problems': problems,
        'pose': {'path': str(POSE).replace('\\', '/'), 'sha256': pose_sha, 'bytes': pose_len},
        'combined_csv': str(OUT_CSV).replace('\\', '/') if not problems else None,
    }
    OUT_JSON.write_text(json.dumps(report, indent=2) + '\n', encoding='utf-8')
    titles = {
        'entry_size_tabs': grab_titles(
            ROOT / 'ref/tasks/T3l-afon-editor-completion/run-20261119-083228/work/out/entry-m3.jsonl',
            'profile', 'profile-size-'),
        'entry_detect_tabs': grab_titles(
            ROOT / 'ref/tasks/T3l-afon-editor-completion/run-20261119-083228/work/out/entry-m3.jsonl',
            'detect', 'detect-'),
        'fix_k2': grab_titles(
            ROOT / 'ref/analysis/button-af/readiness/t3m-afon-editor-state-leak/out/fix-v1.jsonl',
            'k2', ''),
    }
    # The empty prefix above would match every k2 row. Keep size and base ids only.
    titles['fix_k2'] = [row for row in titles['fix_k2'] if row['id'] in ('base',) or row['id'].startswith('size-')]
    OUT_TITLES.write_text(json.dumps(titles, indent=2) + '\n', encoding='utf-8')
    if problems:
        print(json.dumps({'ok': False, 'problems': problems, 'other': len(other), 'profile': len(profile)}))
        raise SystemExit(1)
    with OUT_CSV.open('w', newline='', encoding='utf-8') as f:
        writer = csv.DictWriter(f, fieldnames=fieldnames, lineterminator='\n')
        writer.writeheader()
        writer.writerows(out_rows)
    print(json.dumps({
        'ok': True,
        'rows': len(out_rows),
        'profile_read_diffs': len(profile),
        'other_diffs': len(other),
        'counts': counts,
        'pose': pose_sha,
    }))


if __name__ == '__main__':
    main()
